import { readFileSync, writeFileSync, existsSync } from 'fs';

// Configuration
const THRESHOLD = 20; // 20% minimum quota threshold
const FALLBACK_MODEL = 'google/gemini-3-flash-preview';
const AG_PREFIX = 'google-antigravity/';

