const STATUS_TXT = 'status.txt';

function parseStatusJson() {
  if (!existsSync(STATUS_JSON)) {
    return null;
  }
  try {
    const data = JSON.parse(readFileSync(STATUS_JSON, 'utf-8'));
    return data.defaults?.model?.primary || '';
  } catch (e) {
    return null;
  }
}

function parseStatusText() {
  if (!existsSync(STATUS_TXT)) {
    return {};
  }

  const usageMap = {};
  const content = readFileSync(STATUS_TXT, 'utf-8');
  const lines = content.split('\n');

  // Default gemini models to 100% (infinite quota)
  for (const cand of CANDIDATES) {
    if (cand.includes('gemini')) {
      usageMap[cand] = 100;
    }
  }

  // Parse usage lines
  for (const line of lines) {
    if (line.includes('google-antigravity usage:')) {
      // Match patterns like "claude-opus-4-5-thinking 18% left"
      const regex = /([a-zA-Z0-9-]+) (\d+)% left/g;
      let match;
      while ((match = regex.exec(line)) !== null) {
        let modelName = match[1];
        const percent = parseInt(match[2], 10);

        if (!modelName.startsWith(AG_PREFIX)) {
          modelName = AG_PREFIX + modelName;
        }
        usageMap[modelName] = percent;
      }
    }
  }

  return usageMap;
}

function selectBestModel(usageMap) {
  let bestModel = null;
  let maxPercent = -1;

  for (const model of CANDIDATES) {
    const p = usageMap[model] !== undefined ? usageMap[model] : 0;
    if (p > maxPercent) {
      maxPercent = p;
      bestModel = model;
    }
  }

  return { model: bestModel, percent: maxPercent };
}

function makeDecision(currentModel, usageMap, dryRun = false) {
  const { model: bestModel, percent: maxPercent } = selectBestModel(usageMap);

