    defaults: {
      model: {
        primary: selectedModel
      }
    },
    marker: 'MODEL_GUARD_MARKER_7XQ2'
  };

  writeFileSync(STATUS_JSON, JSON.stringify(statusData, null, 2));
  console.log(message);

  return selectedModel;
}

