    message = currentModel !== selectedModel
      ? "[ModelGuard] Switching to: " + selectedModel + " (" + maxPercent + "%)"
      : "[ModelGuard] Already on optimal model: " + selectedModel + " (" + maxPercent + "%)";
  } else {
