    message = "[ModelGuard] CRITICAL: Max AG quota " + maxPercent + "% < " + THRESHOLD + "%. Fallback to: " + FALLBACK_MODEL;
  }
  if (dryRun) {
    console.log("[DRY-RUN] " + message);
    console.log("Current: " + (currentModel || "(none)"));
    console.log("Selected: " + selectedModel);
    return selectedModel;
  }
  const statusData = { defaults: { model: { primary: selectedModel } }, marker: "MODEL_GUARD_MARKER_7XQ2" };
  writeFileSync(STATUS_JSON, JSON.stringify(statusData, null, 2));
  console.log(message);
  return selectedModel;
}

