  const args = process.argv.slice(2);
  const dryRun = args.includes("--dry-run");
  const currentModel = parseStatusJson();
  const usageMap = parseStatusText();
  const selected = makeDecision(currentModel, usageMap, dryRun);
  process.exit(selected ? 0 : 1);
}

